const body = $input.first().json.body || $input.first().json || {};
let raw = String(body.message ?? body.chatInput ?? '').normalize('NFKC');
// strip control + zero-width characters used to hide injections
raw = raw.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u200B-\u200F\u202A-\u202E\u2060\uFEFF]/g, '').trim();
const thread_id = String(body.thread_id ?? body.sessionId ?? 'default').slice(0,100);
const MAX = 2000;
const text = raw.slice(0, MAX);

const letters = (text.match(/\p{L}/gu) || []).length;
const arabic = (text.match(/[\u0600-\u06FF]/g) || []).length;
const language = letters && arabic / letters > 0.5 ? 'ar' : 'en';

const MSG = {
  blocked: {en:"Sorry, I can't help with that. I can answer questions about our products, orders and store policies.",
            ar:"عذراً، لا أستطيع المساعدة في هذا الطلب. يمكنني الإجابة عن أسئلة المنتجات والطلبات وسياسات المتجر."},
  handover:{en:"I'm passing your request to a human support agent. Someone from our team will contact you soon.",
            ar:"سأحوّل طلبك إلى أحد موظفي خدمة العملاء، وسيتواصل معك فريقنا في أقرب وقت."},
  empty:   {en:"Please type your question and I'll help.", ar:"من فضلك اكتب سؤالك وسأساعدك."}
};

// ---- Guardrails: prompt injection / system prompt extraction ----
const INJECTION = [
  /ignore\s+(all\s+|any\s+)?(the\s+)?(previous|prior|above|earlier)\s+(instructions?|prompts?|rules?)/i,
  /disregard\s+(all\s+|any\s+)?(the\s+)?(previous|prior|above|your)\s+(instructions?|prompts?|rules?)/i,
  /forget\s+(everything|all|your)\s+(you|instructions?|rules?)/i,
  /(reveal|show|print|repeat|display|tell me|leak|output|give me|what('s| is| are))\s+.{0,30}(system\s*prompt|system\s*message|initial\s*prompt|hidden\s*(prompt|instructions?)|your\s+(instructions?|rules|prompt|configuration))/i,
  /system\s*prompt/i,
  /(developer|debug|admin|dan|jailbreak)\s*mode/i,
  /you\s+are\s+now\s+(a|an|in)\s+/i,
  /act\s+as\s+(if\s+you\s+(are|were)|a|an)\s+/i,
  /pretend\s+(to\s+be|you\s+are)/i,
  /(api[\s_-]*key|secret|password|token|credentials?)\s*(of|for|is|:)?\s*(the\s+)?(system|server|n8n|groq|database|admin)/i,
  /<\/?\s*(system|assistant|instructions?)\s*>/i,
  /\[\s*(system|inst)\s*\]/i,
  /(تجاهل|انسَ|انس|تخطى|تخطَّ)\s+.{0,20}(التعليمات|الأوامر|القواعد|ما سبق)/,
  /(اكشف|اظهر|أظهر|اعرض|اطبع|قول|قل|هات|اعطني|أعطني|ورّيني|وريني).{0,30}(التعليمات|البرومبت|الأوامر|الـ?prompt|رسالة النظام|الإعدادات)/i,
  /(برومبت|prompt)\s*(النظام|السيستم|الداخلي)/i,
  /(وضع|مود)\s*(المطور|الأدمن|المدير)/
];
const HANDOVER = [
  /(talk|speak|connect|transfer)\s+(to|with|me)\s+.{0,20}(human|person|agent|representative|someone|manager)/i,
  /(human|real person|live agent|representative|customer service agent)/i,
  /(عايز|عاوز|اريد|أريد|ابغى|أبغى|محتاج).{0,15}(موظف|بشري|شخص|مسؤول|مدير|خدمة العملاء)/,
  /(كلمني|حولني|حوّلني).{0,15}(موظف|حد|شخص)/
];
let early = false, flag = 'none', reply = '';
if (!text) { early = true; flag = 'empty'; reply = MSG.empty[language]; }
else if (INJECTION.some(r => r.test(text))) { early = true; flag = 'blocked'; reply = MSG.blocked[language]; }
else if (HANDOVER.some(r => r.test(text))) { early = true; flag = 'handover'; reply = MSG.handover[language]; }

// ---- Keyword router (free fast path), same keywords as orchestrator.py ----
const KW = {
  rag: ['policy','policies','refund','return','shipping policy','warranty','privacy','terms','employee','hr','leave','passcode',
        'سياسة','سياسات','استرجاع','ارجاع','إرجاع','استرداد','ضمان','خصوصية','شروط','موظف','إجازة'],
  sales: ['buy','purchase','price','cost','recommend','product','discount','cheaper','cart','order','in stock','compare',
        'شراء','اشتري','سعر','أسعار','اسعار','منتج','خصم','عرض','طلب','أوردر','اوردر','متوفر','قارن']
};
const q = text.toLowerCase();
const hits = Object.keys(KW).filter(a => KW[a].some(k => new RegExp('(^|[^\\p{L}])' + k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'), 'u').test(q)));
let keywordAgent = hits.length === 1 ? hits[0] : '';

// ---- Sticky follow-up: remember last agent per thread (works when workflow is active) ----
const sd = $getWorkflowStaticData('global');
sd.last = sd.last || {};
const lastAgent = sd.last[thread_id] || '';
let routeReason = keywordAgent ? 'keyword match' : '';
if (!keywordAgent && lastAgent && text.split(/\s+/).length <= 4) { keywordAgent = lastAgent; routeReason = 'short follow-up'; }

return [{ json: { question: text, thread_id, language, early, flag, reply, keywordAgent, routeReason, lastAgent } }];

const p = $('Prepare & Guardrails').first().json;
const m = {en:"The assistant is temporarily unavailable. A human agent will follow up.", ar:"المساعد غير متاح مؤقتاً. سيتواصل معك أحد موظفينا."};
return [{json:{reply: m[p.language], flag:'kill_switch', thread_id:p.thread_id, language:p.language}}];

