const p = $('Apply English').first().json;
const MIN_CONFIDENCE = 0.5;
let agent = 'rag', confidence = 0, reason = 'fallback';
if (p.keywordAgent) { agent = p.keywordAgent; confidence = 1; reason = p.routeReason; }
else {
  // chainLlm returns the parsed object under output or text depending on version; accept both (or a JSON string)
  const j = $input.first().json;
  let o = null;
  for (let c of [j.output, j.text, j, j.output && j.output.output]) {
    if (typeof c === 'string') { const m = c.match(/\{[\s\S]*\}/); try { c = m ? JSON.parse(m[0]) : null; } catch (e) { c = null; } }
    if (c && typeof c === 'object' && c.agent) { o = c; break; }
  }
  if (o && ['rag','sales'].includes(o.agent)) {
    agent = o.agent; confidence = Number(o.confidence) || 0; reason = String(o.reason || '').slice(0,200);
    if (confidence < MIN_CONFIDENCE) { agent = 'clarify'; reason = 'low confidence, asking the user'; }
  } else { agent = p.lastAgent || 'rag'; }
}
const sd = $getWorkflowStaticData('global'); sd.last = sd.last || {};
if (agent === 'rag' || agent === 'sales') sd.last[p.thread_id] = agent;
return [{ json: { ...p, agent, confidence, routeReason: reason } }];

const p = $input.first().json;
const m = {en:'Do you want to buy something or ask about a policy?', ar:'هل تريد شراء منتج أم الاستفسار عن إحدى السياسات؟'};
return [{json:{reply:m[p.language], flag:'clarify', thread_id:p.thread_id, language:p.language}}];

const p = $('Decide Route').first().json;
const r = $input.first().json;
return [{json:{raw:r, error:r.error||null, agent:'rag', thread_id:p.thread_id, language:p.language, flag:'routed'}}];

const p = $('Decide Route').first().json;
const r = $input.first().json;
return [{json:{raw:r, error:r.error||null, agent:'sales', thread_id:p.thread_id, language:p.language, flag:'routed'}}];

const FALLBACK = {en:'Sorry, I could not get an answer right now. Please try again.', ar:'عذراً، لم أتمكن من الحصول على إجابة الآن. حاول مرة أخرى.'};
const item = $input.first().json;
const lang = item.language || 'en';
let reply = item.reply;
if (reply === undefined) {
  const r = item.raw || {};
  const pick = r.output ?? r.text ?? r.response ?? r.answer ?? r.message ?? (r.data && (r.data.output || r.data.text));
  reply = typeof pick === 'string' ? pick : (Array.isArray(pick) ? pick.map(x => typeof x === 'string' ? x : (x.text||'')).join('\n') : '');
  if (item.error) reply = '';
}
reply = String(reply || '').trim();
// ---- Output guard: never let prompts / keys / internal markers out ----
const LEAK = [/<customer_message>/i, /you are a router/i, /system\s*prompt/i, /\bgsk_[A-Za-z0-9]{10,}/, /\bAIza[0-9A-Za-z_-]{20,}/, /\bsk-[A-Za-z0-9]{16,}/, /\bnvapi-[A-Za-z0-9_-]{10,}/,
              /mongodb(\+srv)?:\/\/[^\s]+/i, /postgres(ql)?:\/\/[^\s]+/i, /AUTOMATION_ENABLED/, /fn_setting/];
let blockedOutput = false;
if (LEAK.some(r => r.test(reply))) { reply = ''; blockedOutput = true; }
if (!reply) reply = FALLBACK[lang];
if (reply.length > 4000) reply = reply.slice(0, 4000);
return [{ json: { reply, agent: item.agent || null, flag: item.flag || null, thread_id: item.thread_id, language: lang, output_blocked: blockedOutput, ts: new Date().toISOString() } }];

// English-first: agents and the router always work on English text.
const p = $('Prepare & Guardrails').first().json;
const t = String($input.first().json.text || '').trim();
const question_en = (p.language === 'ar' && t) ? t : p.question;
return [{ json: { ...p, question_en } }];

const p = $('Decide Route').first().json;
const r = $input.first().json.raw || {};
const pick = r.output ?? r.text ?? r.response ?? r.answer ?? r.message ?? (r.data && (r.data.output || r.data.text));
let reply = typeof pick === 'string' ? pick : (Array.isArray(pick) ? pick.map(x => typeof x === 'string' ? x : (x.text||'')).join('\n') : '');
if ($input.first().json.error) reply = '';
return [{ json: { reply: String(reply || '').trim(), agent: p.agent, flag: 'routed', thread_id: p.thread_id, language: p.language } }];

// Keep the English reply if translation failed.
const p = $('Extract Reply').first().json;
const t = String($input.first().json.text || '').trim();
return [{ json: { ...p, reply: t || p.reply } }];
